const { GoogleGenAI } = require\('@google/genai'\);
const ai = new GoogleGenAI\({ apiKey: process.env.GEMINI_API_KEY_TOTALASSIST }\);

const SYSTEM = 'You are Morgan from TotalAssist. You MUST call presentChoices\(\), showStep\(\), confirmResult\(\), or endSession\(\) on EVERY response. ZERO exceptions. NEVER respond with just text.';

const tools = [{
  functionDeclarations: [
    { name: 'presentChoices', parameters: { type: 'OBJECT', properties: { prompt: { type: 'STRING' }, choices: { type: 'ARRAY', items: { type: 'STRING' } } }, required: ['prompt', 'choices'] } },
    { name: 'showStep', parameters: { type: 'OBJECT', properties: { stepNumber: { type: 'INTEGER' }, title: { type: 'STRING' }, instruction: { type: 'STRING' } }, required: ['stepNumber', 'title', 'instruction'] } },
    { name: 'confirmResult', parameters: { type: 'OBJECT', properties: { question: { type: 'STRING' } }, required: ['question'] } },
    { name: 'endSession', parameters: { type: 'OBJECT', properties: { summary: { type: 'STRING' } }, required: ['summary'] } },
  ]
}];

\(async \(\) => {
  // Simulate a showStep followed by 'Done with this step'
  const contents = [
    { role: 'user', parts: [{ text: 'My router has no lights at all' }] },
    { role: 'model', parts: [
      { text: 'Let me help with that. Let\\\\'s start with checking the power cord.' },
      { functionCall: { name: 'showStep', args: { stepNumber: 1, title: 'Check the power cord', instruction: 'Make sure the power cord is securely plugged into both the router and the wall outlet.' } } }
    ]},
    { role: 'user', parts: [{ functionResponse: { name: 'showStep', response: { result: 'Done with this step — what\\\\'s next?' } } }] },
  ];

  const response = await ai.models.generateContent\({
    model: 'gemini-2.0-flash',
    contents,
    config: { systemInstruction: SYSTEM, temperature: 0.4, tools }
  }\);

  // Inspect raw response structure
  console.log\('=== RAW RESPONSE INSPECTION ==='\);
  console.log\('response.text:', JSON.stringify\(response.text\)\);
  console.log\('response.functionCalls:', JSON.stringify\(response.functionCalls\)\);
  console.log\(''\);

  // Check candidates
  const parts = response.candidates?.[0]?.content?.parts || [];
  console.log\('Parts count:', parts.length\);
  for \(let i = 0; i < parts.length; i++\) {
    const p = parts[i];
    if \(p.text\) console.log\('Part ' + i + ' [text]:', p.text.substring\(0, 100\)\);
    if \(p.functionCall\) console.log\('Part ' + i + ' [functionCall]:', p.functionCall.name, JSON.stringify\(p.functionCall.args\).substring\(0, 150\)\);
  }
}\)\(\).catch\(err => { console.error\('Error:', err.message\); process.exit\(1\); }\);
